import{_ as e,o as i,c as r,ag as a}from"./chunks/framework.BPmc_f4o.js";const u=JSON.parse('{"title":"Built-in Drivers","description":"Reference for all built-in drivers that ship with Muxit — TestDevice, Webcam, ONVIF, FileAccess, Virtual, and MqttBridge.","frontmatter":{"title":"Built-in Drivers","description":"Reference for all built-in drivers that ship with Muxit — TestDevice, Webcam, ONVIF, FileAccess, Virtual, and MqttBridge."},"headers":[],"relativePath":"reference/drivers/index.md","filePath":"reference/drivers/index.md"}'),d={name:"reference/drivers/index.md"};function n(o,t,s,l,h,c){return i(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="built-in-bundled-drivers" tabindex="-1">Built-in &amp; Bundled Drivers <a class="header-anchor" href="#built-in-bundled-drivers" aria-label="Permalink to &quot;Built-in &amp; Bundled Drivers&quot;">​</a></h1><p>Muxit ships with a core set of built-in drivers plus a few bundled extensions — most are always available with no manual installation. The <strong>Vision</strong> engine is the exception: it&#39;s a premium extension, installed from the marketplace and licensed separately on Pro and above. Together these cover testing, cameras, vision, file storage, IoT, notifications, label printing, audio, MIDI, SCPI instruments, and serial protocol work.</p><table tabindex="0"><thead><tr><th>Driver</th><th>Description</th><th>Guide</th></tr></thead><tbody><tr><td><a href="./test-device.html">TestDevice</a></td><td>Simulated instrument for learning and testing</td><td>—</td></tr><tr><td><a href="./webcam.html">Webcam</a></td><td>USB webcam/video capture via OpenCV</td><td>—</td></tr><tr><td><a href="./onvif.html">ONVIF</a></td><td>IP camera streaming, snapshots, and PTZ control</td><td>—</td></tr><tr><td><a href="./vision.html">Vision</a></td><td>Real-time computer vision (color/contour detection) — <strong>premium, requires the <code>vision</code> license</strong></td><td><a href="/guides/ai.html#vision-guided-robot-control">AI Guide — Vision</a></td></tr><tr><td><a href="./file-access.html">FileAccess</a></td><td>Sandboxed file I/O for scripts and AI</td><td>—</td></tr><tr><td><a href="./virtual.html">Virtual</a></td><td>In-memory store with no hardware — share values between scripts and dashboards</td><td><a href="/guides/dashboards.html#virtual-store-pattern">Dashboards Guide</a></td></tr><tr><td><a href="./mqtt-bridge.html">MqttBridge</a></td><td>MQTT broker bridge for IoT devices</td><td><a href="/guides/mqtt-iot.html">MQTT &amp; IoT Guide</a></td></tr><tr><td><a href="./email-notifier.html">EmailNotifier</a></td><td>Outbound SMTP e-mail (text, HTML, attachments)</td><td><a href="/guides/notifications.html">Notifications Guide</a></td></tr><tr><td><a href="./webhook-notifier.html">WebhookNotifier</a></td><td>HTTP webhook with ntfy / Discord / Slack flavors</td><td><a href="/guides/notifications.html">Notifications Guide</a></td></tr><tr><td><a href="./label-printer.html">LabelPrinter</a></td><td>Label printing from JSON templates through any installed printer (templates, barcodes and previews on every tier; printing to a real printer on Pro)</td><td><a href="/guides/label-printing.html">Label Printing Guide</a></td></tr><tr><td><a href="./audio-synth.html">AudioSynth</a></td><td>Software synth for audible notifications on the server host</td><td>—</td></tr><tr><td><a href="./midi.html">Midi</a></td><td>Live MIDI I/O, SMF playback/recording, clock, panic, learn</td><td>—</td></tr><tr><td><a href="./scpi.html">Scpi</a></td><td>Built-in SCPI protocol — declarative, rides on TCP / serial / USB-TMC</td><td>—</td></tr></tbody></table>',3)])])}const f=e(d,[["render",n]]);export{u as __pageData,f as default};
